    """
    Generates a FizzBuzz sequence from 1 up to n (inclusive).

    Rules:
    - If divisible by 3 and 5, returns 'FizzBuzz'.
    - If divisible by 3, returns 'Fizz'.
    - If divisible by 5, returns 'Buzz'.
    - Otherwise, returns the number as a string.
    - If n is less than 1, returns an empty list.
    """
    if n < 1:
        return []

    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

