import re
from collections import Counter

def word_frequency(text: str) -> dict[str, int]:
    """
    Calculates the frequency of each word in the given text.

    Args:
        text: The input string.

    Returns:
        A dictionary where keys are the words (in lowercase) and values 
        are their frequencies. Returns an empty dictionary for an empty string.
    """
    if not text:
        return {}

    # Split the text into words. We use re.findall to robustly find sequences of word characters.
    # Convert all words to lowercase immediately.
    words = re.findall(r'\b\w+\b', text.lower())

    # Use Counter to efficiently count the frequency of each word
    return dict(Counter(words))

if __name__ == '__main__':
    # Test cases
    print(f"Test 1: {word_frequency('Hello world, hello Python!')}")
    # Expected: {'hello': 2, 'world': 1, 'python': 1}

    print(f"Test 2: {word_frequency('This is a test. Test again.')}")
    # Expected: {'this': 1, 'is': 1, 'a': 2, 'test': 2, 'again': 1}

    print(f"Test 3 (Empty): {word_frequency('')}")
    # Expected: {}

    print(f"Test 4 (Only spaces): {word_frequency('   \t\n ')}")
    # Expected: {}
```

