def is_valid_parentheses(s: str) -> bool:
    """
    Checks whether the string s, which consists only of the characters '(', ')', '[', ']', '{' and '}', is valid: 
    every opening bracket must be closed by a bracket of the same type, in the correct order. 
    It returns True if s is valid and False otherwise; an empty string is valid.
    """
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}

    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False
        # Assuming the input string only contains the specified characters, 
        # no need to handle other characters.

    return not stack
