def compute_gcd(a: int, b: int) -> int:
    """
    Computes the greatest common divisor (GCD) of two integers a and b.

    If one of them is 0, the result is the other one.
    """
    # Handle the case where one or both numbers are zero
    if a == 0:
        return abs(b)
    if b == 0:
        return abs(a)

    # Use the Euclidean algorithm for non-negative integers
    # We take the absolute values since GCD is defined for positive integers,
    # and gcd(a, b) = gcd(|a|, |b|)
    a = abs(a)
    b = abs(b)

    while b:
        a, b = b, a % b
    return a
