def decimal_to_binary(n: int) -> str:
    """
    অঋণাত্মক পূর্ণসংখ্যা n-কে তার বাইনারি রূপে রূপান্তর করে একটি স্ট্রিং হিসেবে ফেরত দেয়; 
    স্ট্রিংটিতে '0b' উপসর্গ বা শুরুতে বাড়তি শূন্য থাকে না। 0-এর জন্য ফাংশনটি '0' ফেরত দেয়।
    """
    if n == 0:
