def harmonic_sum(n: int) -> float:
    """
    Calculates the nth harmonic number, which is the sum of the reciprocals of the first n positive integers.
    H_n = 1 + 1/2 + 1/3 + ... + 1/n
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return 0.0

    harmonic_sum_val = 0.0
    for i in range(1, n + 1):
        harmonic_sum_val += 1.0 / i
