def add_matrices(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
    """
    Adds two matrices of the same size element-wise.

    Args:
        a: The first matrix (list of lists of integers).
        b: The second matrix (list of lists of integers).

    Returns:
        A new matrix resulting from the addition, or an empty list if the matrices are not the same size.
    """
    if not a or not b:
        return []

    rows_a = len(a)
    rows_b = len(b)

    if rows_a != rows_b:
        return []

    # Check if all rows have the same number of columns
    try:
        cols_a = len(a[0])
        cols_b = len(b[0])
    except IndexError:
        # This handles cases where a or b might be [[]] but the initial check passed
        return []

    if cols_a != cols_b:
        return []

    # Further check to ensure all rows in both matrices have the same length
    for row in a:
        if len(row) != cols_a:
            return []
    for row in b:
        if len(row) != cols_b:
            return []

    # Perform addition
    result = []
    for i in range(rows_a):
        new_row = []
        for j in range(cols_a):
            new_row.append(a[i][j] + b[i][j])
        result.append(new_row)

    return result

