def parse_kv_pairs(text: str) -> dict[str, str]:
    """
    Parses the string text into a dictionary of key-value pairs.

    The string contains key=value pairs separated by semicolons (;).
    Whitespace around each pair, key and value is removed.
    The key is the part of a pair before its first =, and parts that 
    contain no = are ignored. An empty string gives an empty dictionary.
    """
    if not text:
        return {}

    result = {}
    pairs = text.split(';')

    for pair in pairs:
        pair = pair.strip()
        if not pair:
            continue

        if '=' in pair:
            try:
                key, value = pair.split('=', 1)
                key = key.strip()
                value = value.strip()
                if key:  # Ensure the key is not empty after stripping
                    result[key] = value
            except ValueError:
                # Should not happen if '=' is checked, but good practice
                continue
        # Parts that contain no '=' are ignored

    return result
