from typing import List, Dict

def group_by_mod(nums: List[int], m: int) -> Dict[int, List[int]]:
    """
    Groups integers in nums based on their remainder when divided by m.

    Args:
        nums: A list of integers.
        m: The modulus.

    Returns:
        A dictionary where keys are the remainders (non-negative) and values 
        are lists of numbers from nums that yield that remainder, maintaining 
        the original order. Returns an empty dictionary if m is not positive.
    """
    if m <= 0:
        return {}

    result: Dict[int, List[int]] = {}

    for num in nums:
        # Calculate the non-negative remainder: (num % m + m) % m
        # In Python, % operator handles negative numbers such that the result 
        # has the same sign as the divisor (m). Since m is positive, num % m 
        # will be in the range [-(m-1), m-1]. If num is negative, num % m might be negative.
        # The standard mathematical definition of modulo requires a non-negative result.
        remainder = num % m
        if remainder < 0:
            remainder += m

        if remainder not in result:
            result[remainder] = []

        result[remainder].append(num)

    return result

if __name__ == '__main__':
    # Test cases
    print(f"Test 1: {group_by_mod([1, 5, 2, 8, 3], 3)}")  # Expected: {1: [1, 8], 2: [2], 0: [3, 5]} (Order might vary for keys)
    print(f"Test 2: {group_by_mod([10, 20, 30], 10)}") # Expected: {0: [10, 20, 30]}
    print(f"Test 3: {group_by_mod([1, 2, 3], 5)}")    # Expected: {1: [1], 2: [2], 3: [3]}
    print(f"Test 4 (Negative numbers): {group_by_mod([-1, -5, 1, 4], 3)}") # -1 % 3 = 2, -5 % 3 = 1, 1 % 3 = 1, 4 % 3 = 1. Expected: {2: [-1], 1: [-5, 1, 4]}
    print(f"Test 5 (Empty list): {group_by_mod([], 5)}") # Expected: {}
    print(f"Test 6 (m=0): {group_by_mod([1, 2, 3], 0)}") # Expected: {}
    print(f"Test 7 (m negative): {group_by_mod([1, 2, 3], -2)}") # Expected: {}
