def compact_matrix_dict(matrix: list[list[int]]) -> dict[tuple[int, int], int]:
    """
    Converts a two-dimensional list (matrix) into a dictionary.
    The keys are the tuples (row, column) of the non-zero elements, 
    and the values are those elements. Zero elements are omitted.
    """
    result_dict = {}
    num_rows = len(matrix)
    if num_rows == 0:
        return result_dict

    for r in range(num_rows):
        row = matrix[r]
        num_cols = len(row)
        for c in range(num_cols):
            element = row[c]
            if element != 0:
                result_dict[(r, c)] = element
    return result_dict
