def longest_bitonic_length(nums: list[int]) -> int:
    """
    Returns the length of the longest bitonic subsequence of the list of integers nums.
    A bitonic subsequence keeps the original order of the elements, strictly increases up to one peak element and then strictly decreases; 
    the increasing part or the decreasing part may be empty, so a strictly increasing subsequence, a strictly decreasing subsequence and a subsequence of a single element are all bitonic.
    For an empty list it returns 0.
    """
    n = len(nums)
    if n == 0:
        return 0

    # 1. Compute LIS (Longest Increasing Subsequence) ending at each index i
    # lis[i] stores the length of the LIS ending at nums[i]
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if nums[i] > nums[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # 2. Compute LDS (Longest Decreasing Subsequence) starting at each index i
    # lds[i] stores the length of the LDS starting at nums[i]
    # This is equivalent to LIS on the reversed array up to index n-1-i, but we compute it directly.
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, i, -1):
            if nums[i] > nums[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # 3. Compute the maximum length of the bitonic subsequence
