def run_stack_machine(program: list[str]) -> list[int]:
    """
    Simulates a simple stack machine.

    The machine supports the following operations:
    - PUSH <value>: Pushes the integer <value> onto the stack.
    - POP: Pops the top element from the stack and discards it.
    - ADD: Pops two elements (a and b), computes b + a, and pushes the result.
    - SUB: Pops two elements (a and b), computes b - a, and pushes the result.
    - MUL: Pops two elements (a and b), computes b * a, and pushes the result.
    - DIV: Pops two elements (a and b), computes b / a (integer division), and pushes the result.
    - PRINT: Pops the top element and adds it to the output list.

    Args:
        program: A list of strings representing the program instructions.

    Returns:
        A list of integers representing the values printed by the machine.
    """
    stack = []
    output = []

    for instruction_line in program:
        parts = instruction_line.strip().split()
        if not parts:
            continue

        opcode = parts[0]

        try:
            if opcode == "PUSH":
                value = int(parts[1])
                stack.append(value)
            elif opcode == "POP":
                if stack:
                    stack.pop()
                else:
                    # Handle error case if stack is empty, though problem constraints might assume valid input
                    pass
            elif opcode == "ADD":
                if len(stack) >= 2:
                    a = stack.pop()
                    b = stack.pop()
                    stack.append(b + a)
                else:
                    pass  # Error handling for insufficient operands
            elif opcode == "SUB":
                if len(stack) >= 2:
                    a = stack.pop()
                    b = stack.pop()
                    stack.append(b - a)
                else:
                    pass
            elif opcode == "MUL":
                if len(stack) >= 2:
                    a = stack.pop()
                    b = stack.pop()
                    stack.append(b * a)
                else:
                    pass
            elif opcode == "DIV":
                if len(stack) >= 2:
                    a = stack.pop()
                    b = stack.pop()
                    # Integer division
                    if a != 0:
                        stack.append(b // a)
                    else:
                        # Division by zero handling (e.g., push 0 or raise error)
                        stack.append(0)
                else:
                    pass
            elif opcode == "PRINT":
                if stack:
                    output.append(stack.pop())
                else:
                    pass
            else:
                # Unknown opcode, ignore or raise error
                pass
        except ValueError:
            # Handle case where PUSH argument is not a valid integer
            pass
        except IndexError:
            # Should be caught by length checks, but good practice
            pass

    return output
