def format_table(rows: list[list[str]], aligns: str) -> str:
    """
    Formats a list of lists of strings into a nicely aligned string table.

    Args:
        rows: A list where each element is a list of strings representing a row.
        aligns: A string specifying the alignment for each column.
                'left' (default): Left-aligns content.
                'center': Centers content.
                'right': Right-aligns content.

    Returns:
        A string representing the formatted table.
    """
    if not rows:
        return ""

    num_cols = len(rows[0])
    if num_cols == 0:
        return ""

    # Determine the maximum width for each column
    col_widths = [0] * num_cols
    for row in rows:
        for i in range(min(len(row), num_cols)):
            col_widths[i] = max(col_widths[i], len(row[i]))

    # Determine alignment for each column
    # We assume 'aligns' is a string where each character corresponds to a column's alignment
    # If len(aligns) < num_cols, we default to 'left' for missing alignments.
    column_alignments = []
    for i in range(num_cols):
        if i < len(aligns):
            align = aligns[i].lower()
            if align in ('center', 'right', 'left'):
                column_alignments.append(align)
            else:
                column_alignments.append('left')  # Default if invalid char
        else:
            column_alignments.append('left') # Default if not enough alignment specifiers

    table_lines = []

    # Build the rows
    for row in rows:
        formatted_row_parts = []
        for i in range(num_cols):
            content = row[i] if i < len(row) else ""
            width = col_widths[i]
            alignment = column_alignments[i]

            if alignment == 'left':
                formatted_part = content.ljust(width)
            elif alignment == 'right':
                formatted_part = content.rjust(width)
            elif alignment == 'center':
                formatted_part = content.center(width)
            else:
                # Fallback to left alignment
                formatted_part = content.ljust(width)

            formatted_row_parts.append(formatted_part)

        table_lines.append("".join(formatted_row_parts))

    return "\n".join(table_lines)

