def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    instruction_count = 0
    MAX_INSTRUCTIONS = 1000

    while 0 <= ip < len(program) and instruction_count < MAX_INSTRUCTIONS:
        instruction_line = program[ip].strip()
        parts = instruction_line.split()
        opcode = parts[0]
        ip += 1  # Default increment

        try:
            if opcode == "PUSH":
                n = int(parts[1])
                stack.append(n)
            elif opcode == "POP":
                if not stack:
                    return None
                stack.pop()
            elif opcode == "DUP":
                if not stack:
                    return None
                stack.append(stack[-1])
            elif opcode == "SWAP":
                if len(stack) < 2:
                    return None
                a = stack.pop()
                b = stack.pop()
                stack.append(a)
                stack.append(b)
            elif opcode == "ADD":
                if len(stack) < 2:
                    return None
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
            elif opcode == "SUB":
                if len(stack) < 2:
                    return None
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
            elif opcode == "MUL":
                if len(stack) < 2:
                    return None
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
            elif opcode == "JMP":
