def convert_base(number: str, from_base: int, to_base: int) -> str:
    """
    Converts a number represented as a string from one base to another.

    Args:
        number: The number as a string in the 'from_base'.
        from_base: The original base of the number (e.g., 10 for decimal).
        to_base: The target base for the conversion.

    Returns:
        The number represented as a string in the 'to_base'.

    Raises:
        ValueError: If the input number contains invalid digits for the 'from_base'.
    """

    # Helper function to convert a digit character to its integer value
    def digit_to_value(digit: str) -> int:
        if '0' <= digit <= '9':
            return int(digit)
        elif 'A' <= digit <= 'Z':
            # Assuming uppercase letters for bases > 10 (A=10, B=11, ...)
            return ord(digit) - ord('A') + 10
        else:
            raise ValueError(f"Invalid digit '{digit}' in number string.")

    # Helper function to convert an integer value to its digit character
    def value_to_digit(value: int) -> str:
        if 0 <= value <= 9:
