def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    """
    Simula un montón de arena sobre la cuadrícula rectangular de enteros no negativos.

    Args:
        grid: La cuadrícula inicial de granos de arena.

    Returns:
        La cuadrícula final estabilizada.
    """
    if not grid:
        return []

    rows = len(grid)
    cols = len(grid[0])

