                if current_grid[r][c] >= 4:
                    to_topple.append((r, c))

        if not to_topple:
            break

        # Procesar los derrumbes en el orden en que fueron encontrados
        # Aunque el orden no afecta el resultado final, procesarlos secuencialmente
        # asegura que los cambios se reflejen inmediatamente para la siguiente iteración
        for r, c in to_topple:
            if current_grid[r][c] >= 4:
                # Derrumbe: pierde 4 granos
                current_grid[r][c] -= 4

                # Distribuye 1 grano a cada vecino
                neighbors = [
                    (r - 1, c),  # Arriba
                    (r + 1, c),  # Abajo
                    (r, c - 1),  # Izquierda
                    (r, c + 1)   # Derecha
                ]

                for nr, nc in neighbors:
                    if is_valid(nr, nc):
                        current_grid[nr][nc] += 1

    return current_grid

