    cols = len(grid[0])

    # Create a deep copy of the grid to avoid modifying the original
    current_grid = [row[:] for row in grid]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    while True:
        to_topple = []
        for r in range(rows):
            for c in range(cols):
                if current_grid[r][c] >= 4:
                    to_topple.append((r, c))

        if not to_topple:
            break

        # Process topples. The order doesn't matter for the final state.
        for r, c in to_topple:
            if current_grid[r][c] >= 4:
                # Topple the cell
                current_grid[r][c] -= 4

                # Distribute to neighbors
                neighbors = [
                    (r - 1, c),  # Up
                    (r + 1, c),  # Down
                    (r, c - 1),  # Left
                    (r, c + 1)   # Right
                ]

                for nr, nc in neighbors:
                    if is_valid(nr, nc):
                        current_grid[nr][nc] += 1

