import ast
import operator

def matches_filter(expression: str, record: dict) -> bool:
    """
    Evalúa la expresión de filtro 'expression' para los valores del diccionario 'record' 
    y devuelve True si la expresión es verdadera y False en caso contrario.

    Args:
        expression: La expresión de filtro (string).
        record: El diccionario cuyos valores se usarán en la evaluación.

    Returns:
        bool: El resultado de la evaluación de la expresión.

    Raises:
        ValueError: Si la expresión no es válida o usa un nombre no presente en record.
    """

    # Mapeo de operadores de Python a sus equivalentes en el módulo operator
    OP_MAP = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.And: operator.and_,
        ast.Or: operator.or_,
        ast.Not: operator.not_
    }

    def _eval_node(node):
        """
        Función recursiva para evaluar un nodo AST.
        """
        if isinstance(node, ast.Expression):
            return _eval_node(node.body)

        elif isinstance(node, ast.Constant):
            # Maneja enteros, flotantes, booleanos y cadenas
            if isinstance(node.value, (int, float, bool)):
                return node.value
            elif isinstance(node.value, str):
                return node.value
            else:
                raise ValueError(f"Tipo de constante no soportado: {type(node.value)}")

        elif isinstance(node, ast.Name):
            # Variable (clave de record)
            if node.id in record:
                return record[node.id]
            else:
                raise ValueError(f"Nombre de variable '{node.id}' no encontrado en el registro.")

        elif isinstance(node, ast.BinOp):
            # Operaciones binarias: <, >, ==, and, or
            op_type = type(node.op)
            if op_type in OP_MAP:
                op_func = OP_MAP[op_type]
                left_val = _eval_node(node.left)
                right_val = _eval_node(node.right)
                return op_func(left_val, right_val)
            else:
                raise ValueError(f"Operador binario no soportado: {type(node.op).__name__}")

        elif isinstance(node, ast.UnaryOp):
            # Operaciones unarias: not
            op_type = type(node.op)
            if op_type == ast.Not:
                return not _eval_node(node.operand)
            else:
                raise ValueError(f"Operador unario no soportado: {type(node.op).__name__}")

        elif isinstance(node, ast.Compare):
            # Operaciones de comparación: <, >, ==, etc.
            left_val = _eval_node(node.left)

            # Debe haber exactamente un operador de comparación
            if len(node.ops) != 1:
                raise ValueError("La expresión de comparación debe tener exactamente un operador.")

