def is_local_redirect(target: str, host: str) -> bool:
    """
    Decide si el destino de redirección `target` conduce al sitio cuyo nombre de host es `host`.
    """

    # Condición de exclusión: si target contiene barra invertida, espacio o carácter de control
    if '\\' in target or ' ' in target or re.search(r'[\x00-\x1F\x7F]', target):
        return False

