    # Comienza con una sola '/' y el carácter que sigue a esa '/' (si lo hay) no es '/'
    if target.startswith('/'):
        if len(target) == 1:
            # target es solo "/"
            return False  # No cumple la condición "el carácter que sigue a esa / no es /" si solo es "/"
        elif target[1] != '/':
            return True

    # Caso 2: target es una URL absoluta
    if target.startswith('http://') or target.startswith('https://'):
        try:
            result = urlparse(target)
            # Extraer el hostname, ignorando información de usuario y puerto
            hostname = result.hostname

            if hostname:
                # Comparar el hostname en minúsculas
                return hostname.lower() == host.lower()
