import xml.etree.ElementTree as ET
from typing import List, Dict

def parse_catalog(xml_text: str) -> List[Dict[str, str]]:
    """
    Analiza un texto XML de un catálogo y devuelve una lista de diccionarios,
    uno por cada libro.
    """
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError:
        # Handle case where XML is malformed, although the prompt implies valid structure
        return []

    if root.tag != "catalog":
        # Should not happen based on prompt, but good practice
        return []

    catalog_data: List[Dict[str, str]] = []

    for book_element in root.findall('book'):
        book_id = book_element.get('id', '')

        # Helper function to safely get text from a child element
        def get_text_or_empty(element_name: str) -> str:
            child = book_element.find(element_name)
            if child is not None and child.text is not None:
                return child.text.strip()
            return ""

        title = get_text_or_empty('title')
        author = get_text_or_empty('author')

        catalog_data.append({
            "id": book_id,
            "title": title,
            "author": author
        })

    return catalog_data

import xml.etree.ElementTree as ET

def count_items(xml_text: str) -> int:
    """
    Counts the total number of elements (tags) in the provided XML text.

    Args:
        xml_text: A string containing the XML content.

    Returns:
        The total count of all elements found in the XML.
    """
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError:
        # Handle cases where the XML is malformed
        return 0

    def count_elements(element):
        count = 1  # Count the current element itself
        for child in element:
            count += count_elements(child)
        return count

    return count_elements(root)

